 <el-table :data="rows" v-loading="loading" row-key="series_id"><el-table-column prop="series_id" label="完整序列标识" min-width="220"/><el-table-column label="实际SKU"><template #default="{row}">{{row.item_kind}} #{{row.item_id}}</template></el-table-column><el-table-column prop="as_of" label="原资料截止UTC" min-width="210"/><el-table-column label="治理"><template #default="{row}">{{states[row.status]}} · v{{row.revision}}</template></el-table-column><el-table-column label="操作" width="150"><template #default="{row}"><el-button @click="inspect(row)">核对完整物资序列</el-button></template></el-table-column></el-table>
