const rows=ref([]),total=ref(0),page=ref(1),selected=ref(null),showOriginal=ref(false),loading=ref(false),error=ref(''),creating=ref(false),period=ref({}),preview=ref(null),form=ref(null),action=ref(null),basis=ref('');let epoch=0,alive=true,deactivated=false,observed=false;
