function boundary(){return canonical([store.state.user.accessToken,roles.value,props.itemKind,props.itemId,props.active,props.governance]);}function ticket(){return{epoch:++epoch,boundary:boundary()};}function current(t){return alive&&allowed.value&&t.epoch===epoch&&t.boundary===boundary();}
