function beginAction(value){closeAction();action.value=value;}async function govern(){if(!selected.value||!actionValid.value)return;const original=selected.value,kind=action.value,body={expected_revision:original.revision,expected_content_hash:original.content_hash,basis_note:basis.value,...kind==='revoke'?{}:{decision:kind}};if(!supplySeriesRequestValid(kind==='revoke'?'SeriesRevoke':'SeriesReview',body))return;const t=ticket();loading.value=true;try{const row=(await(kind==='revoke'?revokeSupplySeries:reviewSupplySeries)(original.series_id,body)).data;if(!current(t))return;if(row?.series_id!==original.series_id||row.content_hash!==original.content_hash||row.revision!==original.revision+1||row.status!==(kind==='revoke'?'revoked':kind==='publish'?'published':'rejected')||!await verifySupplySeries(row,{itemKind:props.itemKind,itemId:props.itemId,auditOnly:roles.value.includes('super_admin')}))throw new Error('治理回执不对应本次完整原件或版本');if(!current(t))return;const keys=['status','revision','reviewed_by','reviewed_at','review_basis_note','revoked_by','revoked_at','revoke_reason'],before=Object.fromEntries(keys.map(k=>[k,original[k]])),expected=kind==='revoke'?{...before,status:'revoked',revision:row.revision,revoked_by:row.revoked_by,revoked_at:row.revoked_at,revoke_reason:body.basis_note}:{status:row.status,revision:row.revision,reviewed_by:row.reviewed_by,reviewed_at:row.reviewed_at,review_basis_note:body.basis_note,revoked_by:null,revoked_at:null,revoke_reason:''};if(await digest(expected)!==row.governance_hash)throw new Error('本次治理依据未绑定保存回执');if(!current(t))return;closeAction();selected.value=row;emit('series-changed',{series_id:row.series_id,item_kind:row.item_kind,item_id:row.item_id});}catch(e){failed(t,e);}finally{if(current(t))loading.value=false;}}
